import React, { useState, useEffect } from 'react';

function ProductsList() {
  const [products, setProducts] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('http://localhost/api/products')
      .then(res => {
        if (!res.ok) throw new Error('Error al obtener productos');
        return res.json();
      })
      .then(data => {
        // Ajuste: usar la propiedad "dades" del JSON
        setProducts(data.dades || []);
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching products:', err);
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Cargando productos...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hay productos disponibles.</p>;

  return (
    <div className="row">
      {products.map(product => (
        <div key={product.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">{product.nom}</h5>
              <p className="card-text">{product.descripcio}</p>
              <p className="card-text"><strong>Referencia:</strong> {product.referencia}</p>
              <p className="card-text"><strong>Cantidad:</strong> {product.quantitat}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default ProductsList;
